
# Invisible Oil Loss Detector - Anomaly Validation
# Examine potential oil-loss records generated by feature engineering.

from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
INPUT = ROOT / "outputs" / "production_features.parquet"
OUTPUT = ROOT / "outputs" / "anomaly_validation_summary.csv"


def main():
    print("Loading engineered features...")
    df = pd.read_parquet(INPUT)

    print(f"Total records: {len(df):,}")
    print("\nAvailable columns:")
    print(", ".join(df.columns))

    # Find the existing anomaly flag without changing its definition.
    possible_flags = [
        "possible_invisible_loss",
        "possible_invisible_oil_loss",
        "invisible_loss_flag",
        "is_anomaly",
        "anomaly_flag",
    ]

    flag = next(
        (name for name in possible_flags if name in df.columns),
        None,
    )

    if flag is None:
        print("\nAnomaly flag not found.")
        print("Check the column names printed above.")
        print("No files were changed.")
        return

    # Count records flagged by the existing detection rule.
    flagged = df[df[flag].fillna(False).astype(bool)].copy()

    print(f"\nAnomaly flag: {flag}")
    print(f"Potential oil-loss records: {len(flagged):,}")

    if flagged.empty:
        print("No flagged records available for validation.")
        return

    # Count affected wells and dates.
    if "uwi" in flagged.columns:
        print(f"Affected wells: {flagged['uwi'].nunique():,}")

    if "production_date" in flagged.columns:
        print(
            "Dates with anomalies:",
            f"{flagged['production_date'].nunique():,}",
        )

    # Examine missing information in flagged records.
    columns_to_check = [
        "oil_produced_m3",
        "hours_down",
        "hours_on_prod",
        "pcp_pump_rpm",
        "pump_efficiency_pct",
        "tubing_pressure_kpa",
        "casing_pressure_kpa",
    ]

    summary = []

    for column in columns_to_check:
        if column in flagged.columns:
            summary.append({
                "feature": column,
                "records": len(flagged),
                "missing_values": int(flagged[column].isna().sum()),
                "missing_percent": round(
                    flagged[column].isna().mean() * 100, 2
                ),
            })

    result = pd.DataFrame(summary)
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    result.to_csv(OUTPUT, index=False)

    print("\nMISSING DATA SUMMARY")
    print(result.to_string(index=False))
    print(f"\nSaved: {OUTPUT}")
    print("Initial anomaly validation completed.")
    print("Note: These are candidates, not confirmed oil losses.")


if __name__ == "__main__":
    main()
